  P(12, "pb_p4_trip", "سه همسفر و یک خودروی دونفره", "ریاضیِ مقدماتی (جبر، حرکت)",
    "سه دوست با هم سفر می‌کنند. دو نفرشان پیاده با سرعتِ p راه می‌روند. سومی پایش آسیب دیده و خودرویی دونفره (او و یک نفرِ دیگر) با سرعتِ c می‌راند. روش: با هم راه می‌افتند؛ یکی سوارِ خودرو می‌شود و دیگری پیاده می‌رود. پس از مدتی راننده مسافر را پیاده می‌کند (او پیاده ادامه می‌دهد)، برمی‌گردد تا پیادهٔ عقب‌مانده را سوار کند، و با او جلو می‌رود تا به اولی برسد؛ آن‌جا جای دو پیاده عوض می‌شود و همین تکرار می‌شود. (الف) گروه در هر ساعت چقدر پیش می‌رود؟ (ب) در چه کسری از زمان خودرو فقط راننده را دارد؟ (ج) حالت‌های حدیِ p = 0 و p = c را وارسی کن.",
    "(الف) " + L("c(c + 3p)/(3c + p)") + "؛ (ب) " + L("(c − p)/(3c + p)") + "؛ (ج) با p = 0 سرعت c/3 و کسر ۱/۳ است، و با p = c سرعت c و کسر صفر — هر دو بی‌محاسبه درست‌اند.",
    "شرطِ طولانی و چندمرحله‌ای؛ تا بخش‌هایش جدا و با نمادِ خوب نوشته نشوند، معادله‌ای پیدا نمی‌شود.",
    { unknown: "سرعتِ پیشرفتِ گروه و کسرِ زمانِ تک‌سرنشینی", data: "سرعت‌های p و c", condition: "سه مرحلهٔ هر دور و رسیدنِ همه به یک جا در پایانِ دور" },
    [st("n1", "u", ["mv_equation"], 3, "هر دور سه مرحله دارد: خودرو با مسافرِ اول جلو می‌رود، راننده تنها برمی‌گردد، و خودرو با مسافرِ دوم جلو می‌رود.",
        "کدام نمادگذاری شرط را نوشتنی می‌کند؟",
        [o("زمانِ سه مرحله را t₁، t₂ و t₃ بنام", true, "هر مرحله یک زمان؛ مسافت‌ها با سرعت ضربِ زمان نوشته می‌شوند."),
         o("فاصلهٔ کلِ سفر را D بنام و همان را در معادله بنویس", false, "فاصلهٔ کل داده نشده و به ساختارِ یک دور نمی‌رسد."),
         o("سرعتِ گروه را x بنام و یک معادله حدس بزن", false, "مجهول را نام گذاشتی ولی راهی برای نوشتنِ شرط نساختی.")],
        "نمادِ خوب: یک زمان برای هر مرحله.", "برای هر بخشِ شرط نامی بگذار که نوشتنش ممکن شود.", "در هر مرحله چه کسی با چه سرعتی چقدر حرکت می‌کند؟"),
     st("n2", "p", ["mv_partcond"], 3, "در پایانِ دور هر سه نفر در یک نقطه‌اند.",
        "شرط را به کدام بخش‌های جدا می‌شکنی؟",
        [o("دو پیاده به یک اندازه جلو رفته‌اند؛ راننده سرِ مرحلهٔ دوم به پیادهٔ دوم رسیده", true, "دو بخشِ مستقل ⇐ دو معادله."),
         o("مجموعِ مسافت‌های هر سه نفر برابرِ فاصلهٔ کل است", false, "فاصلهٔ کل در شرط نیست؛ این بخشِ واقعیِ شرط نیست."),
         o("زمانِ هر سه مرحله برابر است چون دور تکرار می‌شود", false, "تکرارِ دور برابریِ مرحله‌ها را نمی‌دهد؛ این فرضِ افزوده است.")],
        "جداکردنِ بخش‌های شرط.", "بخش‌های مختلفِ شرط را جدا کن.", "کسی که پیاده شد و کسی که سوار شد در پایانِ دور کجایند؟"),
     st("n3", "c", ["mv_equation"], 4, "پیادهٔ اول: c·t₁ + p(t₂ + t₃)؛ پیادهٔ دوم: p(t₁ + t₂) + c·t₃؛ راننده در پایانِ t₂ به پیادهٔ دوم می‌رسد.",
        "این دو بخش چه می‌دهند؟",
        [o(L("t₁ = t₃") + " و " + L("t₁/t₂ = (c + p)/(c − p)"), true, "برابریِ دو پیاده ⇒ " + L("(c − p)t₁ = (c − p)t₃") + "؛ رسیدنِ راننده ⇒ " + L("c(t₁ − t₂) = p(t₁ + t₂)") + "."),
         o(L("t₁ = t₂") + " و " + L("t₃ = 2t₁"), false, "از معادله‌ها درنمی‌آید؛ برابریِ دلخواهِ زمان‌هاست."),
         o(L("t₁ + t₂ + t₃ = 1") + " و " + L("t₁ = t₃"), false, "زمانِ دور را می‌شود یک گرفت ولی رابطهٔ دوم را جا انداخته‌ای.")],
        "ترجمهٔ دو بخشِ شرط به دو معادله.", "هر بخش را جدا به معادله ترجمه کن.", "مسافتِ دو پیاده را برابر بگذار."),
     st("n4", "b", ["mv_dimcheck"], 3, "سرعتِ گروه " + L("c(c + 3p)/(3c + p)") + " به دست آمد.",
        "سریع‌ترین وارسی کدام است؟",
        [o("حالت‌های حدی: با p = 0 باید c/3 و با p = c باید c شود", true, "اگر پیاده‌ها نروند، خودرو رفت‌وبرگشت می‌کند ⇒ c/3؛ اگر هم‌سرعت باشند ⇒ c. هر دو برقرارند."),
         o("دیدنِ این‌که عبارت متقارن و زیباست و ساده به نظر می‌رسد", false, "زیبایی وارسی نیست؛ خطای واقعی را نمی‌گیرد."),
         o("گذاشتنِ c = p = 1 و دیدنِ این‌که عدد مثبت است", false, "مثبت بودن آزمونِ ضعیفی است؛ مقدارِ دقیقِ حالتِ حدی را بسنج.")],
        "وارسی با حالت‌های حدی و بُعد (هر دو سرعت‌اند).", "حالت‌های حدی را بی‌محاسبه پیش‌بینی کن و با فرمول بسنج.", "اگر پیاده‌ها اصلاً راه نروند، گروه با چه سرعتی پیش می‌رود؟")],
    ["نمادِ خوب (یک زمان برای هر مرحله) نوشتنِ شرط را ممکن کرد.", "بخش‌های شرط را جدا ترجمه کن.", "حالت‌های حدی را بی‌محاسبه ببین و با فرمول بسنج."]);

